    fn get_history_parent(history: Self::History) -> Self::State {
        match history {}
    }

    // §scxml-3.10.2: a <history>'s default transition target, as written.
    fn get_history_default_targets(
        history: Self::History,
    ) -> &'static [::sce_rust_runtime::EntryTarget<Self::State, Self::History>] {
        match history {}
    }

    fn get_document_order(state: Self::State) -> u32 {
        match state {
            StaticForeachState::Working => 0,
        }
    }

    fn get_event_name(event: Self::Event) -> &'static str {
        match event {
            StaticForeachEvent::A => "a",
            StaticForeachEvent::B => "b",
            StaticForeachEvent::C => "c",
            StaticForeachEvent::Clear => "clear",
            StaticForeachEvent::Count => "count",
            StaticForeachEvent::Cross => "cross",
            StaticForeachEvent::Double => "double",
            StaticForeachEvent::ErrorExecution => "error.execution",
            StaticForeachEvent::Squeeze => "squeeze",
            StaticForeachEvent::Sum => "sum",
            StaticForeachEvent::Weigh => "weigh",
            StaticForeachEvent::Null => "",
        }
    }

    fn get_event_from_name(name: &str) -> Option<Self::Event> {
        match name {
            "a" => Some(StaticForeachEvent::A),
            "b" => Some(StaticForeachEvent::B),
            "c" => Some(StaticForeachEvent::C),
            "clear" => Some(StaticForeachEvent::Clear),
            "count" => Some(StaticForeachEvent::Count),
            "cross" => Some(StaticForeachEvent::Cross),
            "double" => Some(StaticForeachEvent::Double),
            "error.execution" => Some(StaticForeachEvent::ErrorExecution),
            "squeeze" => Some(StaticForeachEvent::Squeeze),
            "sum" => Some(StaticForeachEvent::Sum),
            "weigh" => Some(StaticForeachEvent::Weigh),
            _ => None,
        }
    }

    fn get_state_name(state: Self::State) -> &'static str {
        match state {
            StaticForeachState::Working => "working",
        }
    }

    // The inverse of the table above, emitted from the same loop over the
    // document's states so the two age together. It is what lets a host turn a
    // recorded configuration back into the `StateChain` `enter_at` takes.
    fn get_state_from_name(name: &str) -> Option<Self::State> {
        match name {
            "working" => Some(StaticForeachState::Working),
            _ => None,
        }
    }

    fn null_event() -> Self::Event {
        StaticForeachEvent::Null
    }

